import { createComponent, createContext, useContext } from "solid-js";
export const UiContext = createContext();
function Inner() { useContext(UiContext); return "i"; }
export function Panel(props) { return createComponent(Inner, {}); }
export function Provided(props) { return createComponent(UiContext, { value: 1, get children() { return createComponent(Inner, {}); } }); }
